  vec4 lp = jv_shadowMatrix * (jv_invView * vec4(view_pos, 1.0));
  vec3 c = lp.xyz / lp.w * 0.5 + 0.5;
  if (c.x <= 0.0 || c.x >= 1.0 || c.y <= 0.0 || c.y >= 1.0 || c.z >= 1.0) return 1.0;
  vec2 texel = 1.0 / vec2(textureSize(jv_shadowMap, 0));
  float lit = 0.0;
  for (int x = -1; x <= 1; x++) for (int y = -1; y <= 1; y++) {
    float d = texture(jv_shadowMap, c.xy + vec2(float(x), float(y)) * texel).r;
    lit += c.z - 0.0015 <= d ? 1.0 : 0.0;
  }
  return lit / 9.0;
}
in vec3 jv_v_vertex;
in vec3 jv_v_normal;
in vec2 jv_v_uv;
in vec2 jv_v_uv2;
in vec4 jv_v_color;
